"""Validation rules migrated from legacy/account_rules.vrl."""

from decimal import Decimal
from typing import Any


def _value(record: dict, column: str) -> Any:
    """Return a field value, treating missing fields as the empty string."""
    value = record.get(column, "")
    return "" if value is None else value


def _length(value: Any) -> int:
    """Implement legacy LEN semantics."""
    if value is None:
        return 0
    return len(str(value))


def _number(value: Any) -> Decimal:
    """Coerce a NUMBER value using the legacy empty-string-as-zero rule."""
    if value is None or value == "":
        return Decimal(0)
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def _append_error(
    errors: list[dict],
    code: str,
    message: str,
    severity: str = "BLOCK",
) -> None:
    errors.append(
        {
            "code": code,
            "message": message,
            "severity": severity,
        }
    )


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """Evaluate applicable account rules in legacy rule-file order."""
    del today  # Part of the fixed interface; unused by these five rules.

    errors: list[dict] = []
    applicable = event in ("INSERT", "UPDATE")

    # ACC-001
    if applicable and not (_length(_value(record, "ACCT_NM")) >= 2):
        _append_error(errors, "E1001", "Account name too short")

    # ACC-002
    account_type = _value(record, "ACCT_TYP")
    if applicable and not (
        account_type == "C"
        or account_type == "P"
        or account_type == "R"
        or account_type == "X"
    ):
        _append_error(errors, "E1002", "Invalid account type")

    # ACC-003
    annual_revenue = _value(record, "ANN_REV")
    if applicable and not (_number(annual_revenue) >= Decimal(0)):
        _append_error(errors, "E1003", "Annual revenue negative")

    # ACC-004
    if event == "UPDATE":
        old_credit_hold = _value(old or {}, "CRED_HOLD")
        new_credit_hold = _value(record, "CRED_HOLD")
        credit_limit = _number(_value(record, "CRED_LIMIT"))
        if not (
            not (
                old_credit_hold == "Y"
                and new_credit_hold == "N"
                and credit_limit <= Decimal(0)
            )
        ):
            _append_error(
                errors,
                "E1004",
                "Cannot release credit hold with zero credit limit",
            )

    # ACC-005
    if applicable and not (_length(_value(record, "REGION_CD")) == 3):
        _append_error(
            errors,
            "E1005",
            "Region code must be 3 chars",
            severity="WARN",
        )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any collected validation failure blocks the write."""
    return any(error.get("severity") == "BLOCK" for error in errors)
